func main() {
	rawData := `INSERT INTO aspects_data (planet_1, aspect_type, planet_2, core_meaning, in_reality, strengths, challenges) VALUES ('Sun', 'Conjunction', 'Moon', 'Sự hòa quyện hoàn hảo giữa ý chí (Mặt Trời) và cảm xúc (Mặt Trăng). Một người thống nhất từ trong ra ngoài.', 'Thường hành động theo trực giác và cảm xúc một cách tự nhiên. Rất chân thành nhưng đôi khi thiếu khách quan.', 'Tính toàn vẹn cao, dễ dàng tập trung năng lượng vào một mục tiêu duy nhất. Khả năng thấu hiểu bản thân tốt.', 'Khó tách bạch giữa lý trí và cảm xúc. Dễ bị cuốn vào thế giới nội tâm chủ quan, đôi khi khó nhìn nhận mọi việc từ góc độ người khác.'), ('Sun', 'Sextile', 'Moon', 'Cơ hội phát triển hài hòa giữa cái tôi và thế giới nội tâm. Dễ dàng cân bằng giữa công việc và gia đình.', 'Cuộc sống thường trôi chảy với ít xung đột nội tâm. Dễ thu hút sự giúp đỡ từ người khác nhờ tính cách dễ chịu.', 'Khả năng giao tiếp cảm xúc tốt, duy trì được các mối quan hệ hòa hảo. Trực giác hỗ trợ tốt cho mục tiêu thực tế.', 'Sự thoải mái có thể dẫn đến sự trì trệ hoặc thiếu động lực phấn đấu mãnh liệt nếu không tự đặt ra thử thách.'), ('Sun', 'Square', 'Moon', 'Sự giằng xé nội tâm giữa cái tôi khao khát (Mặt Trời) và nhu cầu an toàn (Mặt Trăng). Động lực lớn để trưởng thành.', 'Thường xuyên cảm thấy mâu thuẫn giữa những gì mình muốn làm và những gì mình cảm thấy cần thiết. Tuổi thơ có thể có sự bất đồng giữa cha mẹ.', 'Động lực phát triển và chứng tỏ bản thân rất lớn. Khả năng vượt qua nghịch cảnh và xây dựng tính cách mạnh mẽ.', 'Dễ bị căng thẳng thần kinh, cảm giác không trọn vẹn. Khó tìm được sự bình yên tĩnh lặng trong tâm hồn.'), ('Sun', 'Trine', 'Moon', 'Sự may mắn và thuận lợi tự nhiên. Năng lượng âm dương hài hòa, tạo ra một cá tính ổn định và bao dung.', 'Thường toát ra sự bình an, tự tin tự nhiên. Ít khi phải đấu tranh gay gắt để đạt được những nhu cầu cơ bản.', 'Dễ dàng thu hút thành công và sự ủng hộ. Nội tâm an ổn, khả năng tự chữa lành tốt, có sức hút tự nhiên với người khác.', 'Có thể quá tự mãn hoặc ỷ lại vào sự may mắn. Thiếu sự sắc bén và quyết liệt cần thiết trong những hoàn cảnh cạnh tranh khốc liệt.'), ('Sun', 'Opposition', 'Moon', 'Sự đối lập giữa ánh sáng và bóng tối, giữa ngoại cảnh và nội tâm. Thường tìm kiếm sự phản chiếu qua các mối quan hệ.', 'Cuộc đời thường là chuỗi các sự kiện đòi hỏi sự thỏa hiệp giữa nhu cầu cá nhân và người khác. Cảm xúc thường trồi sụt mạnh mẽ.', 'Khả năng nhìn nhận vấn đề đa chiều. Rất giỏi trong việc nắm bắt tâm lý người khác khi đã trưởng thành.', 'Khó đạt được sự đồng thuận trong nội tâm. Thường xuyên phóng chiếu cảm xúc của mình lên người khác, gây căng thẳng trong các mối quan hệ thân thiết.'), ('Sun', 'Conjunction', 'Mercury', 'Ý thức và tư duy hợp nhất. Trí tuệ được thắp sáng bởi ý chí cá nhân. Tư duy nhanh nhạy.', 'Luôn muốn biểu đạt bản thân qua lời nói và ý tưởng. Có xu hướng chủ quan trong suy nghĩ và nhận thức.', 'Trí tuệ sắc bén, giao tiếp mạnh mẽ, khả năng thuyết phục và truyền đạt ý tưởng xuất sắc.', 'Đôi khi quá bảo thủ hoặc cái tôi lấn át lý trí. Khó tách biệt cảm xúc cá nhân ra khỏi các cuộc tranh luận khách quan.'), ('Sun', 'Sextile', 'Mercury', 'Giao tiếp trôi chảy và cơ hội học hỏi phong phú. Dễ dàng chia sẻ ý tưởng với thế giới xung quanh.', 'Thích học hỏi, đọc sách và trao đổi ý kiến. Mạng lưới quan hệ xã hội hỗ trợ tốt cho sự nghiệp.', 'Khả năng tư duy logic và thực tế, giao tiếp duyên dáng, dễ tiếp thu kiến thức mới.', 'Không có nhiều thách thức lớn, tuy nhiên có thể thiếu đi chiều sâu nếu chỉ dừng ở việc tiếp thu thông tin bề mặt.'), ('Sun', 'Square', 'Mercury', 'Mâu thuẫn giữa cách thể hiện bản thân và cách tư duy (dù ít khi xảy ra trong thực tế do góc giới hạn của Thủy Tinh).', 'Thường cảm thấy bị hiểu lầm hoặc ý tưởng của mình bị cản trở bởi hoàn cảnh khách quan.', 'Động lực lớn để trau dồi kỹ năng giao tiếp và tư duy phản biện. Luôn tò mò và tìm tòi.', 'Dễ lo âu, căng thẳng thần kinh, hoặc vội vã đưa ra quyết định mà thiếu sự cân nhắc kỹ lưỡng.'), ('Sun', 'Trine', 'Mercury', 'Tư duy thông suốt, mạch lạc và hài hòa với ý chí cá nhân. (Hiếm gặp do Thủy Tinh luôn ở gần Mặt Trời).', 'Trí tuệ tự nhiên phát triển mạnh mẽ. Dễ dàng thành công trong các lĩnh vực liên quan đến viết lách, giao tiếp.', 'Tài hùng biện tự nhiên, suy nghĩ nhạy bén, tiếp thu nhanh và biết cách truyền đạt hiệu quả.', 'Có thể trở nên lười biếng về mặt trí tuệ nếu không được đặt vào môi trường đòi hỏi sự tư duy sâu sắc.'), ('Sun', 'Opposition', 'Mercury', 'Sự đối lập giữa cái tôi và thế giới ý tưởng (Góc này không tồn tại trong thực tế thiên văn học vì Mặt Trời và Thủy Tinh không bao giờ cách nhau quá 28 độ).', 'Không áp dụng trong biểu đồ thực tế.', 'Không áp dụng trong biểu đồ thực tế.', 'Không áp dụng trong biểu đồ thực tế.'), ('Sun', 'Conjunction', 'Venus', 'Sự kết hợp giữa bản ngã và tình yêu, cái đẹp. Trái tim và mong muốn được tỏa sáng hòa làm một.', 'Rất quan tâm đến ngoại hình và cách người khác đánh giá mình. Tỏa ra sức hút quyến rũ, ấm áp.', 'Sự duyên dáng tự nhiên, khiếu thẩm mỹ tốt, tính cách hòa đồng, dễ được người khác yêu mến.', 'Cái tôi có thể phụ thuộc quá nhiều vào tình yêu hoặc sự tán thưởng của người khác. Có nguy cơ phù phiếm.'), ('Sun', 'Sextile', 'Venus', 'Cơ hội kết nối xã hội tốt. Năng lượng sáng tạo và nghệ thuật tuôn chảy tự nhiên.', 'Cuộc sống thường có nhiều niềm vui từ nghệ thuật, tình bạn và các mối quan hệ xã hội. Dễ dàng hòa nhập.', 'Khả năng ngoại giao tuyệt vời, biết cách làm hài lòng người khác mà không đánh mất bản thân.', 'Đôi khi thiếu sự sâu sắc trong các mối quan hệ do có xu hướng né tránh những xung đột cần thiết.'), ('Sun', 'Square', 'Venus', 'Sự xung đột giữa nhu cầu thể hiện bản ngã và mong muốn hòa hợp (Hiếm gặp do Kim Tinh không bao giờ cách Mặt Trời quá 48 độ).', 'Không áp dụng trong biểu đồ thực tế.', 'Không áp dụng trong biểu đồ thực tế.', 'Không áp dụng trong biểu đồ thực tế.'), ('Sun', 'Trine', 'Venus', 'Sự hài hòa và may mắn trong tình cảm và tài chính (Góc này không tồn tại trong thực tế thiên văn học).', 'Không áp dụng trong biểu đồ thực tế.', 'Không áp dụng trong biểu đồ thực tế.', 'Không áp dụng trong biểu đồ thực tế.'), ('Sun', 'Opposition', 'Venus', 'Sự đối lập giữa cái tôi và các giá trị (Góc này không tồn tại trong thực tế thiên văn học).', 'Không áp dụng trong biểu đồ thực tế.', 'Không áp dụng trong biểu đồ thực tế.', 'Không áp dụng trong biểu đồ thực tế.'), ('Sun', 'Conjunction', 'Mars', 'Sự hợp nhất của ý chí và hành động. Động lực mạnh mẽ, can đảm và khao khát chinh phục.', 'Rất quyết đoán, đôi khi vội vàng bốc đồng. Thích cạnh tranh và luôn muốn là người dẫn đầu.', 'Năng lượng dồi dào, lòng dũng cảm, khả năng lãnh đạo và tinh thần tiên phong không ngại khó khăn.', 'Cái tôi quá lớn, dễ nóng giận, thiếu kiên nhẫn. Có xu hướng áp đặt ý chí lên người khác, gây mâu thuẫn.'), ('Sun', 'Sextile', 'Mars', 'Năng lượng hành động hỗ trợ cho mục tiêu của bản ngã. Biết cách sử dụng sức mạnh một cách khéo léo.', 'Làm việc năng suất, quyết định nhanh gọn nhưng vẫn có sự chừng mực. Thường đạt được mục tiêu dễ dàng.', 'Sự nhiệt tình, khả năng làm việc độc lập tốt, sự tự tin truyền cảm hứng cho người khác.', 'Có thể thiếu sự táo bạo tột đỉnh nếu mọi thứ quá thuận lợi. Cần đặt ra thách thức lớn hơn để phát huy tối đa.'), ('Sun', 'Square', 'Mars', 'Mâu thuẫn giữa cái tôi và hành động. Năng lượng thường bùng nổ và khó kiểm soát. Tính cạnh tranh cao.', 'Thường xuyên đối mặt với các xung đột hoặc cảm giác phải chiến đấu để bảo vệ cái tôi. Dễ bực bội.', 'Sức mạnh to lớn được sinh ra từ áp lực. Động lực vươn lên mạnh mẽ, không khuất phục trước khó khăn.', 'Tính khí nóng nảy, hung hăng, bốc đồng dễ dẫn đến sai lầm hoặc tai nạn. Cần học cách kiểm soát cơn giận và cái tôi.'), ('Sun', 'Trine', 'Mars', 'Dòng chảy năng lượng hành động mượt mà, tự nhiên. Hành động bản năng thường mang lại kết quả tốt.', 'Tự tin, thể thao, nhiều năng lượng tích cực. Dễ dàng thuyết phục người khác làm theo ý mình mà không cần ép buộc.', 'Lòng dũng cảm tự nhiên, thể lực tốt, khả năng tự hồi phục nhanh chóng, tính cách cởi mở, sảng khoái.', 'Có thể quá tự mãn với khả năng của mình, thiếu tính kỷ luật do mọi thứ thường đạt được quá dễ dàng.'), ('Sun', 'Opposition', 'Mars', 'Sự đụng độ giữa cái tôi và mong muốn hành động. Thường gặp xung đột với người khác về quyền lực.', 'Thường xuyên rơi vào các cuộc tranh cãi hoặc cạnh tranh đối kháng. Dễ cảm thấy bị người khác khiêu khích.', 'Khả năng thấu hiểu sự cạnh tranh và chiến đấu. Nếu trưởng thành, có thể trở thành người đàm phán sắc bén.', 'Xu hướng đối đầu bốc đồng. Cái tôi dễ bị tổn thương, dẫn đến phản ứng thái quá. Cần học cách kiềm chế.'), ('Sun', 'Conjunction', 'Jupiter', 'Sự mở rộng cái tôi, niềm tin và sự lạc quan. Tự tự thái quá và tầm nhìn xa.', 'Luôn nhìn đời qua lăng kính màu hồng. Thích sự tự do, khám phá, học hỏi và truyền cảm hứng.', 'Sự lạc quan vô tận, lòng hào phóng, vận may bẩm sinh, khả năng thu hút sự thịnh vượng và bảo vệ.', 'Có thể quá tự cao tự đại, kiêu ngạo, đánh giá quá cao khả năng của mình, thiếu sự tiết chế và dễ lãng phí.'), ('Sun', 'Sextile', 'Jupiter', 'Cơ hội phát triển thông qua tri thức, niềm tin và sự lạc quan. May mắn nhỏ luôn đồng hành.', 'Thích học hỏi, du lịch, và mở rộng tầm nhìn. Dễ thu hút sự giúp đỡ từ những người có quyền thế hoặc trí tuệ.', 'Trí tuệ triết học, lòng tốt bụng, khả năng nhìn nhận những cơ hội phát triển. Giao tiếp cởi mở.', 'Nếu không hành động, cơ hội sẽ trôi qua. Có thể quá an phận với những may mắn nhỏ bé mà quên đi tiềm năng lớn.'), ('Sun', 'Square', 'Jupiter', 'Sự xung đột giữa mong muốn phát triển và khả năng thực tế. Có xu hướng làm mọi thứ quá mức.', 'Thường hứa hẹn nhiều hơn những gì có thể làm. Đôi khi quá mạo hiểm trong đầu tư hoặc niềm tin.', 'Tham vọng to lớn, động lực không ngừng vươn tới sự vĩ đại. Tinh thần dám nghĩ dám làm.', 'Sự kiêu ngạo quá mức, mù quáng trước rủi ro. Cần học bài học về sự khiêm tốn và giới hạn của bản thân.'), ('Sun', 'Trine', 'Jupiter', 'May mắn và sự bảo vệ tự nhiên. Bản ngã và niềm tin hòa quyện tạo ra một tâm hồn cao thượng.', 'Cuộc sống dường như luôn có bàn tay vô hình che chở. Rất rộng lượng và thường xuyên gặp may mắn.', 'Lòng khoan dung, triết lý sống sâu sắc, khả năng lan tỏa năng lượng tích cực, dễ dàng thành công.', 'Dễ sinh ra tâm lý ỷ lại, lười biếng, thiếu động lực phấn đấu vì mọi thứ luôn có xu hướng "đâu vào đấy".'), ('Sun', 'Opposition', 'Jupiter', 'Sự giằng xé giữa cái tôi cá nhân và các nguyên tắc đạo đức hoặc xã hội rộng lớn hơn.', 'Thường xuyên đứng giữa ranh giới của sự tự phụ và sự hối hận. Có thể gặp vấn đề trong việc cân bằng mong muốn.', 'Sự hiểu biết sâu sắc về các giới hạn xã hội. Khả năng phát triển một hệ thống niềm tin vững chắc qua thử thách.', 'Có xu hướng đạo đức giả hoặc cố gắng thể hiện mình lớn lao hơn thực tế. Cần tìm sự cân bằng giữa bản thân và cộng đồng.'), ('Sun', 'Conjunction', 'Saturn', 'Trách nhiệm, kỷ luật và giới hạn hòa làm một với cái tôi. Cảm giác gánh nặng hoặc sự nghiêm túc từ sớm.', 'Thường chín chắn trước tuổi, làm việc chăm chỉ, nhưng đôi khi quá khắt khe với bản thân. Ít khi bộc lộ sự hồn nhiên.', 'Tính kiên nhẫn phi thường, tinh thần trách nhiệm cao, khả năng tổ chức và xây dựng nền tảng vững chắc.', 'Thiếu tự tin bẩm sinh, cảm giác không đủ giỏi, tự giới hạn bản thân, dễ rơi vào trạng thái u sầu hoặc trầm cảm.'), ('Sun', 'Sextile', 'Saturn', 'Sự cân bằng hoàn hảo giữa sáng tạo và kỷ luật. Làm việc có phương pháp và hiệu quả.', 'Dễ dàng tổ chức cuộc sống, có tính kiên nhẫn bẩm sinh để theo đuổi các mục tiêu dài hạn một cách đều đặn.', 'Sự bền bỉ, tính logic, khả năng làm việc chăm chỉ mà không cảm thấy kiệt sức, nhận được sự tôn trọng từ cấp trên.', 'Đôi khi quá nguyên tắc, thiếu sự ngẫu hứng và tính phiêu lưu trong cuộc sống hàng ngày.'), ('Sun', 'Square', 'Saturn', 'Sự xung đột gay gắt giữa khát vọng thể hiện (Mặt Trời) và những rào cản, luật lệ (Thổ Tinh).', 'Thường xuyên cảm thấy bị cản trở bởi hoàn cảnh hoặc người có thẩm quyền (đặc biệt là người cha). Áp lực thành công lớn.', 'Sức mạnh ý chí phi thường được rèn dũa qua nghịch cảnh. Khả năng vượt qua những giới hạn tưởng chừng không thể.', 'Cảm giác tự ti sâu sắc, thường xuyên tự chỉ trích. Cần cẩn thận với sự cứng nhắc và tính cách quá độc đoán khi nắm quyền.'), ('Sun', 'Trine', 'Saturn', 'Sự hỗ trợ của kỷ luật và cấu trúc đối với bản ngã. Thành công đến chậm nhưng cực kỳ vững chắc.', 'Sống thực tế, biết cách lập kế hoạch và có trách nhiệm. Ít khi gặp khó khăn lớn liên quan đến quyền lực.', 'Sự khôn ngoan bẩm sinh, tinh thần trách nhiệm, khả năng lãnh đạo bền vững, đáng tin cậy.', 'Có thể quá an toàn, ngại thay đổi hoặc thiếu sự phá cách cần thiết để tạo ra những bước nhảy vọt đột phá.'), ('Sun', 'Opposition', 'Saturn', 'Sự đối lập giữa bản ngã và giới hạn. Cảm giác thường xuyên bị thế giới bên ngoài hoặc người khác kiểm tra, đánh giá.', 'Thường cảm thấy áp lực từ các kỳ vọng xã hội hoặc mối quan hệ. Đấu tranh giữa việc được là chính mình và làm theo quy tắc.', 'Khả năng đánh giá khách quan về bản thân và thế giới. Khi vượt qua được, sẽ trở thành những nhà lãnh đạo vô cùng công tâm.', 'Sự ức chế nội tâm, luôn cảm thấy bị hạn chế, xu hướng phòng thủ cao. Cần học cách thư giãn và tin tưởng bản thân.'), ('Sun', 'Conjunction', 'Uranus', 'Bản ngã nổi loạn, độc lập và thiên tài. Cái tôi hòa nhập với sự đổi mới và tự do tuyệt đối.', 'Tính cách lập dị, thích phá vỡ các quy tắc, hành động bất ngờ và khó đoán. Luôn tìm kiếm sự mới mẻ.', 'Khả năng sáng tạo đột phá, trực giác nhạy bén, tư duy vượt thời đại, lòng can đảm để là một cá thể khác biệt.', 'Quá nổi loạn, thiếu kiên nhẫn với những điều bình thường, dễ thay đổi bốc đồng, khó làm việc theo nhóm hoặc tuân thủ kỷ luật.'), ('Sun', 'Sextile', 'Uranus', 'Cơ hội phát triển thông qua sự đổi mới và những thay đổi đột ngột nhưng tích cực.', 'Thường xuyên có những ý tưởng sáng tạo, dễ dàng áp dụng công nghệ mới. Có mạng lưới bạn bè độc đáo.', 'Tính độc lập, trí tuệ cởi mở, khả năng nắm bắt xu hướng tương lai, sự quyến rũ khác biệt.', 'Đôi khi có thể lơ lãng, thiếu sự cam kết lâu dài nếu không có sự thay đổi liên tục.'), ('Sun', 'Square', 'Uranus', 'Sự căng thẳng giữa nhu cầu ổn định của bản ngã và nhu cầu nổi loạn của Uranus. Thay đổi đột ngột.', 'Cuộc sống thường xuyên trải qua những biến động bất ngờ. Khó chịu với sự áp đặt, phản ứng mạnh mẽ khi bị hạn chế.', 'Động lực to lớn để phá vỡ các khuôn mẫu cũ kỹ. Năng lượng cải cách mạnh mẽ, không khuất phục.', 'Tính khí thất thường, cực đoan, quyết định liều lĩnh. Cần học cách cân bằng giữa tự do cá nhân và sự ổn định thiết yếu.'), ('Sun', 'Trine', 'Uranus', 'Sự đổi mới và tính độc đáo tuôn chảy tự nhiên. Sự tự do không gặp nhiều rào cản.', 'Dễ dàng thể hiện cá tính riêng mà không gây xung đột lớn. Thích khám phá và thử nghiệm những điều mới mẻ.', 'Khả năng thấu hiểu những kiến thức phi truyền thống, sự linh hoạt bẩm sinh, dễ dàng thích nghi với sự thay đổi.', 'Có thể thiếu sự tập trung sâu sắc, dễ cả thèm chóng chán, thiếu sự cam kết với những mục tiêu đòi hỏi sự kiên nhẫn dài hạn.'), ('Sun', 'Opposition', 'Uranus', 'Sự đối lập giữa cái tôi và sự hỗn loạn. Thường xuyên thu hút những người hoặc hoàn cảnh bất thường.', 'Thường trải qua các mối quan hệ đột ngột bắt đầu hoặc kết thúc. Cảm thấy luôn phải đấu tranh bảo vệ tự do cá nhân.', 'Khả năng thức tỉnh bản thân qua các cú sốc bên ngoài. Tầm nhìn khách quan và không phán xét.', 'Gặp khó khăn trong việc thiết lập sự ổn định nội tâm. Xu hướng đẩy người khác ra xa khi cảm thấy bị ràng buộc.'), ('Sun', 'Conjunction', 'Neptune', 'Bản ngã hòa tan vào thế giới vô hình, mộng tưởng và tâm linh. Ranh giới cá nhân mờ nhạt.', 'Rất nhạy cảm, giàu trí tưởng tượng, thường sống trong thế giới riêng. Dễ đồng cảm nhưng cũng dễ bị ảnh hưởng bởi môi trường.', 'Trực giác tâm linh sâu sắc, khả năng nghệ thuật đỉnh cao, lòng trắc ẩn, tính vị tha và khả năng chữa lành.', 'Khó xác định cái tôi thực sự, dễ bị lừa dối, ảo tưởng, trốn tránh thực tại qua các chất gây nghiện hoặc sự hy sinh sai lầm.'), ('Sun', 'Sextile', 'Neptune', 'Trực giác và trí tưởng tượng hỗ trợ tự nhiên cho việc thể hiện bản thân.', 'Thích nghệ thuật, âm nhạc, có đời sống tâm linh phong phú nhưng không bị tách rời thực tế.', 'Khả năng sáng tạo nghệ thuật, trực giác nhạy bén, lòng trắc ẩn tự nhiên, sức hút tinh tế.', 'Đôi khi có thể quá mơ mộng, thiếu quyết đoán trong những hoàn cảnh đòi hỏi hành động thực tế.'), ('Sun', 'Square', 'Neptune', 'Sự giằng xé giữa thực tại rõ ràng của Mặt Trời và thế giới ảo ảnh của Neptune.', 'Thường gặp khó khăn trong việc nhận thức đúng đắn về bản thân hoặc hoàn cảnh. Dễ bị thất vọng hoặc cảm thấy lạc lõng.', 'Động lực lớn để đi sâu vào việc tìm kiếm ý nghĩa tâm linh và sự thật nội tâm. Khả năng nghệ thuật mãnh liệt.', 'Ảo tưởng về bản thân hoặc người khác, xu hướng tự biến mình thành nạn nhân, dễ lạc lối trong những mục tiêu không thực tế.'), ('Sun', 'Trine', 'Neptune', 'Dòng chảy tự nhiên của nguồn cảm hứng tâm linh và nghệ thuật.', 'Sống rất vị tha, giàu tình cảm, có khả năng nhìn thấy vẻ đẹp trong mọi thứ. Trực giác dẫn đường rất chính xác.', 'Tâm hồn lãng mạn, khả năng nghệ thuật bẩm sinh, kết nối tâm linh sâu sắc, đem lại sự yên bình cho người khác.', 'Thiếu tính thực tế, có thể quá thụ động, phó mặc mọi chuyện cho số phận mà không chịu nỗ lực cá nhân.'), ('Sun', 'Opposition', 'Neptune', 'Sự đối lập giữa cái tôi rõ ràng và sự mờ mịt của người khác hoặc hoàn cảnh.', 'Thường xuyên phóng chiếu những lý tưởng hoặc ảo tưởng của mình lên người khác. Dễ thất vọng trong các mối quan hệ.', 'Khả năng thấu cảm sâu sắc, khi trưởng thành có thể trở thành người chữa lành hoặc nghệ sĩ tài năng.', 'Gặp khó khăn trong việc thiết lập ranh giới rõ ràng. Dễ bị lừa gạt hoặc lợi dụng tình cảm.'), ('Sun', 'Conjunction', 'Pluto', 'Bản ngã hợp nhất với quyền lực sâu thẳm, sự biến đổi và bóng tối. Tính cách dữ dội.', 'Sống một cuộc sống đầy những lần tái sinh. Rất kiểm soát, đam mê mãnh liệt, luôn muốn đào sâu vào bản chất sự việc.', 'Sức mạnh tâm lý phi thường, khả năng vượt qua khủng thực, từ tính bẩm sinh, sức bền bỉ kiên cường.', 'Ám ảnh về quyền lực và sự kiểm soát. Cái tôi thao túng, ghen tuông, đa nghi, khó buông bỏ tổn thương.'), ('Sun', 'Sextile', 'Pluto', 'Cơ hội phát triển thông qua sự biến đổi chậm rãi và hiểu biết sâu sắc.', 'Biết cách sử dụng sức mạnh cá nhân một cách tinh tế. Thích nghiên cứu tâm lý hoặc những điều bí ẩn.', 'Khả năng tự phân tích tốt, sức hút ngầm, sự kiên định trong việc theo đuổi mục tiêu.', 'Không có thách thức lớn, tuy nhiên có thể thiếu đi sự phá hủy cần thiết để tái sinh mạnh mẽ hơn.'), ('Sun', 'Square', 'Pluto', 'Xung đột mạnh mẽ giữa bản ngã bề mặt và những khát vọng sâu kín, quyền lực. Khủng hoảng liên tục.', 'Thường xuyên đối mặt với các cuộc chiến quyền lực, sự phản bội hoặc những biến cố thay đổi cuộc đời.', 'Khả năng tái sinh từ đống tro tàn. Năng lượng phi thường được đánh thức qua nghịch cảnh.', 'Tính cách cực đoan, xu hướng phá hoại hoặc tự hủy hoại. Cần đối mặt với bóng tối nội tâm thay vì đàn áp nó.'), ('Sun', 'Trine', 'Pluto', 'Dòng chảy tự nhiên của sức mạnh cá nhân và khả năng biến đổi.', 'Thường có ảnh hưởng lớn đến người khác mà không cần tốn nhiều sức. Dễ dàng tự làm mới bản thân sau thất bại.', 'Sự tự tin bẩm sinh, khả năng lãnh đạo bẩm sinh, từ tính mạnh mẽ, có thể nắm giữ quyền lực một cách tự nhiên.', 'Có thể lạm dụng sức mạnh bẩm sinh hoặc thiếu sự đồng cảm với những người yếu thế hơn.'), ('Sun', 'Opposition', 'Pluto', 'Sự đối lập giữa cái tôi và các thế lực quyền lực bên ngoài. Đấu tranh quyền lực trong các mối quan hệ.', 'Thường thu hút những cá nhân có tính cách kiểm soát, thao túng hoặc nguy hiểm. Cảm thấy bản thân bị đe dọa.', 'Khả năng nhìn thấu bản chất con người và các động cơ ẩn giấu. Rất sắc sảo trong việc đọc vị người khác.', 'Có xu hướng thao túng người khác hoặc bị thao túng. Ám ảnh cưỡng chế, cần học cách buông bỏ và tin tưởng.') ;`

	valuesStr := strings.TrimPrefix(rawData, "INSERT INTO aspects_data (planet_1, aspect_type, planet_2, core_meaning, in_reality, strengths, challenges) VALUES ")
	valuesStr = strings.TrimSpace(valuesStr)
	valuesStr = strings.TrimSuffix(valuesStr, ";")

	ctx := context.Background()
	conn, err := pgx.Connect(ctx, "postgres://zodiac_user:zodiac_pass@localhost:5432/zodiac_db?sslmode=disable")
	if err != nil {
		log.Fatalf("Unable to connect to database: %v\n", err)
	}
	defer conn.Close(ctx)

	// In the seed script, p1 and p2 are sorted alphabetically! So Sun (S) comes AFTER Moon (M).
	// To match the database properly, we must sort them so factor_value_1 <= factor_value_2.
	
	insertQuery := fmt.Sprintf(`
		WITH data(planet_1, aspect_type, planet_2, core_meaning, in_reality, strengths, challenges) AS (
			VALUES %s
		)
		INSERT INTO placement_interpretations (
			language, factor_type, factor_value_1, factor_value_3, factor_value_2,
			core_meaning, real_life, strengths, challenges, relationships, growth_path
		)
		SELECT 
			'vi', 
			'aspect', 
			CASE WHEN planet_1 < planet_2 THEN planet_1 ELSE planet_2 END, 
			lower(aspect_type), 
			CASE WHEN planet_1 < planet_2 THEN planet_2 ELSE planet_1 END,
			core_meaning, in_reality, strengths, challenges, '', ''
		FROM data
		ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3)
		DO UPDATE SET
			core_meaning = EXCLUDED.core_meaning,
			real_life = EXCLUDED.real_life,
			strengths = EXCLUDED.strengths,
			challenges = EXCLUDED.challenges,
			relationships = EXCLUDED.relationships,
			growth_path = EXCLUDED.growth_path,
			updated_at = CURRENT_TIMESTAMP;
	`, valuesStr)

	tag, err := conn.Exec(ctx, insertQuery)
	if err != nil {
		log.Fatalf("Insert failed: %v", err)
	}

	fmt.Printf("Successfully inserted/updated sorted data! Rows affected: %d\n", tag.RowsAffected())
	
	// Delete any old uppercase records that we might have inserted by mistake previously
	conn.Exec(ctx, "DELETE FROM placement_interpretations WHERE language='vi' AND factor_type='aspect' AND factor_value_3 IN ('Conjunction', 'Opposition', 'Trine', 'Square', 'Sextile')")
}
